/// Feeds key presses to `on_key` until it returns an exit code; `Err` once input can no longer be read.
fn read_keys(
    mut next: impl FnMut() -> std::io::Result<Event>,
    mut on_key: impl FnMut(KeyEvent) -> Option<i32>,
) -> std::io::Result<i32> {
    loop {
