fn spawn_keyboard_thread(session: Arc<WatchSession>, exit_code: Arc<AtomicI32>) {
    std::thread::spawn(move || {
        if let Err(error) = crossterm::terminal::enable_raw_mode() {
            tracing::warn!("key shortcuts unavailable: {error}");
            return;
